#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets these two at the top of the stages section.
TOTAL_STAGES=0
TOTAL_MINUTES=0

_STAGE_INDEX=0
_MINUTES_ELAPSED=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does and how long it takes.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages · about %s minutes%s\n\n' \
    "$DIM" "$TOTAL_STAGES" "$TOTAL_MINUTES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" <minutes> — clear the screen, then announce a stage and show
# progress + time remaining. Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  local remaining=$((TOTAL_MINUTES - _MINUTES_ELAPSED))
  (( remaining < 0 )) && remaining=0
  _MINUTES_ELAPSED=$((_MINUTES_ELAPSED + ${2:-0}))
  printf '\n%s%s▸ Stage %s/%s · %s%s  %s(~%s min left)%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET" "$DIM" "$remaining" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set the two totals to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

GUILD_ID=1357557811281793054

# Connects the home page's newsletter signup to Sender (ADR 0024). Sets the
# GitHub Actions secrets SENDER_API_TOKEN and SENDER_GROUP_ID, which
# deploy-live.yml writes into nginx on the droplet. The token is read hidden,
# handed to curl and gh on stdin only, and never written to disk.

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$REPO_ROOT"
ENV_FILE=/dev/null
SENDER_API_TOKEN=''
trap 'SENDER_API_TOKEN=' EXIT
API=https://api.sender.net/v2

# sender_curl ARGS… — curl against the Sender API with the token in curl's
# stdin config, so it never appears in the process list. Extra config lines
# (a JSON body, say) can be passed in SENDER_EXTRA_CONFIG.
sender_curl() {
  { printf 'header = "Authorization: Bearer %s"\n' "$SENDER_API_TOKEN"
    printf 'header = "Accept: application/json"\n'
    if [[ -n "${SENDER_EXTRA_CONFIG:-}" ]]; then printf '%s\n' "$SENDER_EXTRA_CONFIG"; fi
  } | curl -s -K - "$@"
}

# The same check deploy-live.yml makes before it writes the token into nginx.
renders_safely() {
  SENDER_API_TOKEN="$SENDER_API_TOKEN" SENDER_GROUP_ID="${1:-x}" \
    bash deploy/nginx/render-sender-secret.sh >/dev/null 2>&1
}

# groups_table — reads GET /v2/groups JSON on stdin, prints "id<TAB>title" lines.
# The response shape is assumed ({ data: [{ id, title }] }), not documented; if
# it differs, nothing is listed and the human pastes the id instead.
groups_table() {
  node -e '
    let s = ""; process.stdin.on("data", (c) => s += c).on("end", () => {
      const groups = (JSON.parse(s).data || []);
      for (const g of groups) console.log(`${g.id}\t${g.title ?? g.name ?? ""}`);
    });'
}

TOTAL_STAGES=6
TOTAL_MINUTES=20

banner "Cinema Slime — Sender newsletter setup"

stage "Create the Sender account" 5
say "Links open on this machine's browser if it can; otherwise open them on yours."
open_url "https://app.sender.net/signup"
step "Sign up with the brand's address (cinemaslimepodcast@gmail.com) and confirm it."
step "The free plan is enough: it covers 2,500 subscribers."
step "Settings → General settings: fill in the company postal address."
note "Every campaign footer carries it. Sender won't send without one."
pause "Account created and address filled in?"

stage "Verify a sending domain" 8
step "Settings → Account settings → Domains  ·  add cinemaslime.com."
step "Add the DNS records Sender shows at the domain's DNS host, then click Verify."
note "DNS can take a while. You can carry on now and come back to the Verify button later;"
note "signups work without it, only sending a campaign needs it."
pause "Domain added?"

stage "Create an API token" 2
step "Settings → API access tokens  ·  Create API token."
step "Name it: cinemaslime.com newsletter  ·  Validity: Forever  ·  Create."
step "Copy the token. It is shown only once."
note "It grants full access to the account, which is why only the droplet's nginx ever holds it."
for attempt in 1 2 3 4 5 6; do
  (( attempt < 6 )) || { warn "Giving up after 5 tries; nothing was stored."; exit 1; }
  ask_secret SENDER_API_TOKEN "Paste the API token (hidden):"
  SENDER_API_TOKEN="${SENDER_API_TOKEN//[[:space:]]/}"
  if ! renders_safely; then
    warn "That token has characters the deploy refuses to write into nginx. Copy it again."
    continue
  fi
  code=$(sender_curl -o /dev/null -w '%{http_code}' "$API/groups")
  [[ "$code" == 200 ]] && break
  warn "Sender rejected that token (HTTP $code). Create a new one and paste it."
done
say "Token works."

stage "Pick the group signups join" 2
say "Every signup from the site is added to one group, so you can mail exactly them."
while :; do
  groups=$(sender_curl "$API/groups" | groups_table 2>/dev/null || true)
  if [[ -n "$groups" ]]; then
    say "Groups on the account:"
    i=0
    while IFS=$'\t' read -r gid gtitle; do
      i=$((i + 1)); printf '    %s%2d%s  %s  %s(%s)%s\n' "$BOLD" "$i" "$RESET" "$gtitle" "$DIM" "$gid" "$RESET"
    done <<< "$groups"
  else
    warn "No groups listed (none yet, or Sender answered in a shape this wizard doesn't know)."
  fi
  step "To make one: Subscribers → Groups → Create group, name it 'Website signups', then come back."
  ask GROUP_CHOICE "Type a group's number, paste a group id, or press Enter to list again:"
  [[ -n "$GROUP_CHOICE" ]] || continue
  SENDER_GROUP_ID="$GROUP_CHOICE"
  if [[ "$GROUP_CHOICE" =~ ^[0-9]{1,3}$ ]] && (( GROUP_CHOICE >= 1 )) && [[ -n "$groups" ]]; then
    SENDER_GROUP_ID=$(sed -n "${GROUP_CHOICE}p" <<< "$groups" | cut -f1)
  fi
  if [[ -n "$SENDER_GROUP_ID" ]] && renders_safely "$SENDER_GROUP_ID"; then break; fi
  warn "That isn't a group on the list or a usable group id (letters and digits only)."
done
say "Signups will join group $SENDER_GROUP_ID."

stage "Store the GitHub secrets" 1
set_secret SENDER_API_TOKEN "$SENDER_API_TOKEN"
set_secret SENDER_GROUP_ID "$SENDER_GROUP_ID"
note "deploy-live.yml refuses to deploy until both are set; the next push to live writes them into nginx."

stage "Optional: try a real signup" 2
say "Subscribes an address you type, twice, straight through Sender's API, and shows both answers."
say "Sender doesn't document what a repeat signup returns; this settles it."
if confirm "Run it?"; then
  # The site's own check, so the smoke test only tries addresses it would send.
  while :; do
    ask SMOKE_EMAIL "An address you own:"
    node --input-type=module -e "import { isValidEmail } from './src/newsletter.js'; process.exit(isValidEmail(process.argv[1]) ? 0 : 1)" "$SMOKE_EMAIL" && break
    warn "The site's signup wouldn't accept that address. Try another."
  done
  body=$(printf '{\\"email\\":\\"%s\\",\\"groups\\":[\\"%s\\"]}' "$SMOKE_EMAIL" "$SENDER_GROUP_ID")
  first=$(SENDER_EXTRA_CONFIG="header = \"Content-Type: application/json\"
data = \"$body\"" sender_curl -o /dev/null -w '%{http_code}' -X POST "$API/subscribers")
  second=$(SENDER_EXTRA_CONFIG="header = \"Content-Type: application/json\"
data = \"$body\"" sender_curl -o /dev/null -w '%{http_code}' -X POST "$API/subscribers")
  say "First signup:  HTTP $first"
  say "Second signup: HTTP $second"
  if [[ "$first" =~ ^20[01]$ && "$second" =~ ^20[01]$ ]]; then
    say "Both are 2xx, so a repeat signup shows the visitor the same success. Nothing to change."
  else
    warn "A repeat signup answers $second. The site shows anything but 204 as \"try again in a bit\"."
    warn "Tell Claude these two numbers so the edge can be taught what a repeat means."
  fi
  note "Remove the test subscriber in Subscribers if you don't want it."
fi

finish
say "Next: merge to live. The deploy writes the token into nginx and the signup goes live."
